CREATE VIEW vw_game_conditional_similarity AS SELECT GameKey, GameID, GameTitle, round(avg(CASE  WHEN (((PreferenceTier = 'A') AND (ConditionalFlag = CAST('t' AS BOOLEAN)))) THEN (similarity_pct) ELSE NULL END), 2) AS avg_conditional_similarity, round(max(CASE  WHEN (((PreferenceTier = 'A') AND (ConditionalFlag = CAST('t' AS BOOLEAN)))) THEN (similarity_pct) ELSE NULL END), 2) AS max_conditional_similarity FROM vw_game_seed_similarity GROUP BY GameKey, GameID, GameTitle;
